// Modul zachovává kontrakt workeru DocFX a vyhledává indexovaná česká i anglická slova.
import { createSearchIndex, searchIndex } from './search-core.mjs';

let index = [];
let ready = false;

async function loadIndex() {
  const response = await fetch('../index.json');
  if (!response.ok) {
    throw new Error(`Vyhledávací index se nepodařilo načíst: HTTP ${response.status}`);
  }

  index = createSearchIndex(await response.json());
  ready = true;
  postMessage({ e: 'index-ready' });
}

/**
 * Zpracuje inicializaci a dotazy přijaté ze stránky DocFX.
 *
 * @param {MessageEvent} event Zpráva workeru DocFX.
 */
function handleSearchMessage({ data }) {
  if (typeof data?.q === 'string' && ready) {
    postMessage({ e: 'query-ready', d: searchIndex(index, data.q) });
  } else if (data?.init && !ready) {
    loadIndex().catch(console.error);
  }
}

onmessage = handleSearchMessage;
